import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.RQXGjTIX.js";const p=JSON.parse('{"title":"气压与容量换算","description":"","frontmatter":{},"headers":[],"relativePath":"guide/pressure.md","filePath":"guide/pressure.md"}'),o={name:"guide/pressure.md"};function s(i,t,l,n,h,c){return d(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="气压与容量换算" tabindex="-1">气压与容量换算 <a class="header-anchor" href="#气压与容量换算" aria-label="Permalink to &quot;气压与容量换算&quot;">​</a></h1><p>CCB 的气体只有三个基本量，容量和气压都是推出来的。</p><table tabindex="0"><thead><tr><th>量</th><th>单位</th><th>说明</th></tr></thead><tbody><tr><td>气体量</td><td><strong>GU</strong>（整数）</td><td>世界里只存在&quot;多少 GU&quot;</td></tr><tr><td>体积</td><td><strong>升 L</strong></td><td>配置里写 kL，1 kL = 1,000 L</td></tr><tr><td>压力</td><td><strong>Pa</strong></td><td>100,000 Pa = 1 atm = CCB 的参考压力</td></tr></tbody></table><h2 id="核心公式" tabindex="-1">核心公式 <a class="header-anchor" href="#核心公式" aria-label="Permalink to &quot;核心公式&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>压力(Pa) = 气体量(GU) × 100,000 / 体积(L)</span></span>
<span class="line"><span>气体量(GU) = 体积(L) × 压力(Pa) / 100,000</span></span></code></pre></div><ul><li><strong>1 GU = 1 升气体 @ 100 kPa（1 atm）</strong>，反过来 1 kGU = 1 m³ @1 atm；</li><li>CCB 的 1 atm 严格取 <strong>100,000 Pa</strong>（不是 101,325 Pa）；</li><li>压力是<strong>推导量，不存储</strong>：每次由当前 GU 和体积现算，所以储罐扩容后同量气体压力立刻下降。</li></ul><h2 id="容量-体积-×-承压上限" tabindex="-1">容量 = 体积 × 承压上限 <a class="header-anchor" href="#容量-体积-×-承压上限" aria-label="Permalink to &quot;容量 = 体积 × 承压上限&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>maxAmount(GU) = 体积(L) × maxPressure(Pa) / 100,000</span></span></code></pre></div><table tabindex="0"><thead><tr><th>档位</th><th>压力</th><th>Pa</th><th>含义</th></tr></thead><tbody><tr><td>SAFE</td><td>16 atm</td><td>1,600,000</td><td>正常运行上限</td></tr><tr><td>HARD</td><td>24 atm</td><td>2,400,000</td><td>物理硬上限（任何储罐不得超过）</td></tr></tbody></table><h3 id="常见容器" tabindex="-1">常见容器 <a class="header-anchor" href="#常见容器" aria-label="Permalink to &quot;常见容器&quot;">​</a></h3><table tabindex="0"><thead><tr><th>容器</th><th>体积</th><th>承压</th><th>满容量</th></tr></thead><tbody><tr><td>密封储罐 <code>airtighttank</code></td><td>80 kL / 方块</td><td>HARD 24 atm</td><td><strong>1,920,000 GU</strong></td></tr><tr><td>同上按安全线</td><td>80 kL</td><td>SAFE 16 atm</td><td>1,280,000 GU</td></tr><tr><td>气罐（物品）</td><td>2 kL</td><td>10 atm</td><td>20,000 GU</td></tr><tr><td>ME 气体接口缓冲罐</td><td>8,000 L</td><td>24 atm</td><td>192,000 GU</td></tr><tr><td>气体 P2P 隧道面</td><td>4,000 L</td><td>16 atm</td><td>64,000 GU</td></tr></tbody></table><h2 id="传输的规则" tabindex="-1">传输的规则 <a class="header-anchor" href="#传输的规则" aria-label="Permalink to &quot;传输的规则&quot;">​</a></h2><ul><li>流动条件是 <strong>源压力 &gt; 目标压力</strong>（相等不流动）；</li><li>向目标注气时，目标压力上限取 <code>min(源压力, 目标承压上限)</code>；</li><li>真正的吞吐瓶颈是<strong>流量上限</strong>：泵 4,000 GU/t（最多 +4 atm 压升）、调节泵 4,000 GU/t（单级 +8 atm）、 密封舱门 20,000 GU/s、Breeze Chamber 5,120 GU/s；</li><li>速率还会随转速、入口压力（低于 1 atm 时衰减）与反向压差下降。</li></ul><h2 id="算例" tabindex="-1">算例 <a class="header-anchor" href="#算例" aria-label="Permalink to &quot;算例&quot;">​</a></h2><ol><li><strong>80 kL 储罐打到 16 atm</strong>：<code>80,000 × 1,600,000 / 100,000 = 1,280,000 GU</code></li><li><strong>500,000 GU 放进空的 80 kL 罐</strong>：<code>500,000 × 100,000 / 80,000 = 625,000 Pa = 6.25 atm</code></li><li><strong>1k 气体元件（1,024,000 GU）全打进空 80 kL 罐</strong>： <code>1,024,000 × 100,000 / 80,000 = 1,280,000 Pa = 12.8 atm</code>（在安全线内）</li></ol><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>别用 101,325 Pa 算——CCB 全流程用 <strong>100,000 Pa</strong>；</li><li>压力不是罐的固定属性，而是&quot;当前量 / 当前体积&quot;的结果；</li><li>超过 16 atm 不是&quot;更划算的存储&quot;：会积累过压应力，24 atm 下约 5 秒破裂；</li><li>容量决定&quot;最多装多少&quot;，泵 / 舱门 / 管路的 GU/t 决定&quot;多久装满&quot;。</li></ul>`,17)])])}const m=a(o,[["render",s]]);export{p as __pageData,m as default};
